 const combatState={reportDate:today()};let combatRoles={},combatAnalysis=null;const toast=api.toast,rosterOrderOf=p=>api.people().findIndex(x=>x.personId===p.personId),outputName=p=>p.person.alias||p.person.name.slice(-2);
