function combatMatchGroup(info,groups,used){const name=combatNormalizeText(info.name);let found=groups.find(g=>!used.has(g)&&combatNormalizeText(g.name)===name);if(!found&&info.range)found=groups.find(g=>!used.has(g)&&combatCourseRange(g.start,g.end)===info.range);return found||null}
