function buildCombatReport(){const a=combatAnalysis;if(!a)return;const count=k=>+($(`[data-combat-count="${k}"]`)?.value||0),secondLeave=count('leave'),secondTraining=a.trainingStart>=0?count('training'):0;let lines=rebuildCombatTraining(a,secondTraining);for(let i=Math.max(a.zone1End+1,a.zone2Header,0);i<=Math.min(a.zone2Title,lines.length-1);i++){if(combatRole(i,lines[i])==='fixed')continue;lines[i]=lines[i].replace(/(放\s*假\D{0,8})\d+/,(_,p)=>p+secondLeave);if(a.trainingStart>=0)lines[i]=lines[i].replace(/(受\s*訓\D{0,8})\d+/,(_,p)=>p+secondTraining)}if(a.totalLine>=0&&combatRole(a.totalLine,a.lines[a.totalLine])!=='fixed')lines[a.totalLine]=`共計：${a.canonical.leaveCount+secondLeave}員`;const zone1=[`📌資料時間：${md(combatState.reportDate)}`,`🎉放假:${a.canonical.leaveCount}員 受訓：${a.canonical.trainingCount}員`,'一區隊',...a.canonical.leaves.map(combatLeaveLine),...a.lines.slice(a.zone1Start,a.zone1End+1).filter((line,i)=>combatRole(a.zone1Start+i,line)==='fixed'),''];lines.splice(a.zone1Start,a.zone1End-a.zone1Start+1,...zone1);const result=lines.join('\n');$('#combatResult').value=result;$('#combatDiff').innerHTML=`<div><h4>原一區</h4><pre>${esc(a.lines.slice(a.zone1Start,a.zone1End+1).join('\n'))}</pre></div><div><h4>新一區</h4><pre>${esc(zone1.join('\n'))}</pre></div>${a.warnings.length?`<div class="combat-note">⚠️ ${esc(a.warnings.join('｜'))}</div>`:''}`;$('#combatResultSection').classList.remove('combat-hidden');$('#combatResultSection').scrollIntoView({behavior:'smooth',block:'start'})}
